<?php else: ?><p><strong><?= Security::e($invoice['invoice_number']) ?></strong> · Status: <?= Security::e($invoice['status']) ?> · Brutto: <?= $money($invoice['gross_cents']) ?></p><p>Empfänger: <?= Security::e($invoice['recipient_name']) ?>, <?= Security::e($invoice['recipient_email']) ?></p><a class="button ghost" target="_blank" href="<?= Security::e(I18n::url('/verwaltung/rechnungen/'.(int)$invoice['id'].'/pdf')) ?>"><?= $invoice['status']==='cancelled'?'Storno-PDF anzeigen':'Finale PDF anzeigen' ?></a><?php if($invoice['status']==='cancelled'): ?> <a class="button ghost" target="_blank" href="<?= Security::e(I18n::url('/verwaltung/rechnungen/'.(int)$invoice['id'].'/original-pdf')) ?>">Unveränderte Originalrechnung</a><?php endif; ?>
