<?php if(in_array($invoice['status'],['finalized','sent'],true)): ?><form method="post" action="<?= Security::e(I18n::url('/verwaltung/rechnungen/'.(int)$invoice['id'].'/bezahlt')) ?>" class="admin-form"><?= Security::csrfField() ?><label>BEZAHLT eingeben<input name="confirmation" required></label><button>Zahlung dokumentieren</button></form><?php endif; ?>
<?php if($invoice['status']!=='cancelled'): ?><form method="post" action="<?= Security::e(I18n::url('/verwaltung/rechnungen/'.(int)$invoice['id'].'/stornieren')) ?>" class="admin-form"><?= Security::csrfField() ?><label>Stornierungsgrund<textarea name="reason" required maxlength="500"></textarea></label><label>STORNIEREN eingeben<input name="confirmation" required></label><button>Rechnung stornieren</button></form><?php endif; ?>
