<section class="admin-card admin-card-wide"><h2>Bestehende Rechnungen</h2><div class="table"><table><thead><tr><th>Nummer</th><th>Empfänger</th><th>Datum</th><th>Status</th><th>Brutto</th></tr></thead><tbody><?php foreach($invoices as $row): ?><tr><td><a href="<?= Security::e(I18n::url('/verwaltung/rechnungen/'.(int)$row['id'])) ?>"><?= Security::e($row['invoice_number']?:'Entwurf #'.$row['id']) ?></a></td><td><?= Security::e($row['recipient_name']) ?></td><td><?= Security::e($row['invoice_date']) ?></td><td><?= Security::e($row['status']) ?></td><td><?= $money($row['gross_cents']) ?></td></tr><?php endforeach; ?></tbody></table></div></section></section>
<script>
(()=>{const table=document.querySelector('#items tbody');if(!table)return;document.querySelector('#add-item').addEventListener('click',()=>{const r=table.rows[0].cloneNode(true);r.querySelectorAll('input').forEach(i=>{i.value=i.name.includes('quantity')?'1,000':i.name.includes('unit_price')?'0,00':i.name.includes('tax_rate')?'19,00':i.name.includes('unit')?'Stück':''});table.append(r)});table.addEventListener('click',e=>{if(e.target.classList.contains('remove-item')&&table.rows.length>1)e.target.closest('tr').remove()});document.querySelector('#copy-recipient')?.addEventListener('click',()=>{const o=document.querySelector('#recipient-source').selectedOptions[0];if(!o?.dataset.recipient)return;const d=JSON.parse(o.dataset.recipient);for(const k of ['name','email','street','postal_code','city','country'])document.querySelector('#recipient-'+k.replace('_','-')).value=d[k]||'';document.querySelector('#member-id').value=d.type==='member'?d.id:0;document.querySelector('#user-id').value=d.type==='user'?d.id:0});})();
</script>
